import csv, os
p = os.path.join(os.environ["PANTHEON_PROJECTS"], "shop/sales.csv")
rows = list(csv.DictReader(open(p, newline="", encoding="utf-8-sig")))
print("columns", list(rows[0]), "rows", len(rows))
for r in rows[:3]: print(r)
def kind(v):
    try: float(v); return "number"
    except ValueError: return "date" if v[:4].isdigit() and v[4:5] == "-" else "text"
for c in rows[0]: print(c, kind(rows[0][c]), len({r[c] for r in rows}), "distinct")

